float4 raytrace(Ray ray, const Scene& scene) {
    float closest = INFINITY;
    HitRecord hit;
    for (const Object& obj : scene.objects) {
        float t = obj.intersect(ray);
        if (t > EPS && t < closest) {
            closest = t;
            hit = obj.hit(ray, t);
        }
    }
